def sequence(n):
    """
    This function generates the newman conway sequence up to the nth number.

    Args:
        n: The number of elements to generate in the sequence.

    Returns:
        A list containing the first n elements of the newman conway sequence.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]
    else:
        list_seq = [0, 1]
        for i in range(2, n):
            next_num = list_seq[i - 1] + list_seq[i - 2]
            list_seq.append(next_num)
        return list_seq

