def count_char_position(str1):
    """Counts the number of characters in a string that occur at the same
    position in the English alphabet (case insensitive).
    """
    count = 0
    for char in str1:
        if 'a' <= char.lower() <= 'z':
            position = ord(char.lower()) - ord('a') + 1
            if char.lower() == chr(ord('a') + position - 1):
                count += 1
    return count

