def cal_sum(n):
    """Calculates the sum of the first n Perrin numbers."""
    if n <= 0:
        return 0
    elif n == 1:
        return 3
    elif n == 2:
        return 3 + 0 = 3
    elif n == 3:
        return 3 + 0 + 2 = 5

    perrin_numbers = [3, 0, 2]
    sum_perrin = 5

    for i in range(3, n):
        next_perrin = perrin_numbers[i - 2] + perrin_numbers[i - 3]
        perrin_numbers.append(next_perrin)
        sum_perrin += next_perrin

    return sum_perrin

