    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    if a == b:
        return None
    else:
        if isinstance(a, str):
            try:
                a_float = float(a.replace(",", "."))
            except ValueError:
                return a
        else:
            a_float = float(a)
        if isinstance(b, str):
            try:
                b_float = float(b.replace(",", "."))
            except ValueError:
                return b
        else:
            b_float = float(b)
        if a_float > b_float:
            return a
        else:
            return b  # Return b when a_float is smaller

