def get_max_sum(n):
    """
    Finds the maximum sum possible by using the given equation
    f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n).

    Args:
        n: An integer.

    Returns:
        The maximum sum.
    """
    if n <= 0:
        return 0

    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        max_sum = n
        if i >= 2:
            max_sum = max(max_sum, dp[i // 2] + dp[i // 3] + dp[i // 4] + dp[i // 5])
        if i >= 3:
            max_sum = max(max_sum, dp[i // 2] + dp[i // 3] + dp[i // 4] + dp[i//6])  
        if i >= 4:
             max_sum = max(max_sum, dp[i // 2] + dp[i // 3] + dp[i // 4] + dp[i // 5] + dp[i // 8])
        if i>=5:
             max_sum = max(max_sum, dp[i // 2] + dp[i // 3] + dp[i // 4] + dp[i // 5] + dp[i//6] + dp[i//7])

        if i >= 6:
           max_sum = max(max_sum, dp[i//2] + dp[i//3] + dp[i//4] + dp[i//5] + dp[i//6] + dp[i//7] + dp[i//8] + dp[i//9])
        dp[i] = max_sum

    return dp[n]

