def recursive_list_sum(data_list):
    """
    Recursively sums all elements in a list, including nested lists.

    Args:
        data_list: A list potentially containing nested lists.

    Returns:
        The sum of all numerical elements in the list.
    """
    total = 0
    for element in data_list:
        if isinstance(element, list):
            total += recursive_list_sum(element)
        else:
            try:
                total += element
            except TypeError:
                pass  # Ignore non-numerical elements
    return total

