    Generates the nth number in the newman conway sequence.

    Args:
        n: The index of the desired number in the sequence (starting from 0).

    Returns:
        The nth number in the newman conway sequence.
    """
    if n == 0:
        return 1
    elif n == 1:
        return 1
    elif n == 2:
        return 2
    elif n == 3:
        return 3
    elif n == 4:
        return 5
    elif n == 5:
        return 8
    elif n == 6:
        return 13
    else:
