def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 10
    if n == 2:
        return 10

    start_with_one = 10**(n-1)
    end_with_one = 1

    for i in range(1, 10):
        if i == 1:
            continue
        end_with_one *= i

    return start_with_one + end_with_one - 1 # subtract the number that starts and ends with 1

