def cal_sum(n):
    """
    Calculate the sum of the first n Perrin numbers.

    Args:
        n: The number of Perrin numbers to sum.

    Returns:
        The sum of the first n Perrin numbers.
    """
    if n <= 0:
        return 0

    perrin_numbers = [0, 1, 1]
    if n <= 3:
        return sum(perrin_numbers[:n])

    for i in range(3, n):
        next_perrin = perrin_numbers[i - 2] + perrin_numbers[i - 3]
        perrin_numbers.append(next_perrin)

    return sum(perrin_numbers)

