def get_max_sum(n):
    """
    Finds the maximum sum possible by using the given equation f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n).

    Args:
      n: The input integer.

    Returns:
      The maximum sum possible.
    """
    if n <= 0:
        return 0

    memo = {}

    def calculate_max_sum(num):
        if num in memo:
            return memo[num]

        if num == 1:
            return num

        max_sum = num
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                max_sum = max(max_sum, calculate_max_sum(num // i) + i)

        max_sum = max(max_sum, calculate_max_sum(num // 2) + num // 2 if num // 2 > 0 else num)
        max_sum = max(max_sum, calculate_max_sum(num // 3) + num // 3 if num // 3 > 0 else num)
        max_sum = max(max_sum, calculate_max_sum(num // 4) + num // 4 if num // 4 > 0 else num)
        max_sum = max(max_sum, calculate_max_sum(num // 5) + num // 5 if num // 5 > 0 else num)

        memo[num] = max_sum
        return max_sum

    return calculate_max_sum(n)

