def is_undulating(n):
    """
    Check whether the given number is undulating or not.

    A number is undulating if the difference between any two adjacent digits is not constant.
    For example, 1234321 is undulating because the differences between adjacent digits are 1, -1, 1, -1, 1.
    """
    s = str(n)
    if len(s) < 3:
        return False

    diffs = []
    for i in range(len(s) - 1):
        diffs.append(int(s[i+1]) - int(s[i]))

    for i in range(len(diffs) - 1):
        if diffs[i] == diffs[i+1]:
            return False

    return True

