    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 10
    else:
        start_with_1 = 10**(n-1)
        end_with_1 = 1
        for i in range(1, n):
            end_with_1 *= 9
        return start_with_1 + end_with_1 - 1

